use serde::{Deserialize, Serialize};

/// Types that can do specific "health check" for Nix

pub trait Checkable {
    /// Run and create the health check
    ///
    /// NOTE: Some checks may perform impure actions (IO, etc.). Returning an
    /// empty vector indicates that the check is skipped on this environment.
    fn check(
        &self,
        nix_info: &nix_rs::info::NixInfo,
        // The flake against which the check is being run
        //
        // If None, the check is run against the current environment, with no
        // specific configuration from a flake.
        flake: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check>;
}

/// A health check
#[derive(Debug, Serialize, Deserialize, PartialEq, Eq, Clone)]
pub struct Check {
    /// A user-facing title of this check
    ///
    /// This value is expected to be unique across all checks.
    pub title: String,

    /// The user-facing information used to conduct this check
    /// TODO: Use Markdown
    pub info: String,

    /// The result of running this check
    pub result: CheckResult,

    /// Whether this check is mandatory
    ///
    /// Failures are considered non-critical if this is false.
    pub required: bool,
}

/// The result of a health [Check]
#[derive(Debug, Serialize, Deserialize, PartialEq, Eq, Clone)]
pub enum CheckResult {
    /// The check passed
    Green,

    /// The check failed
    Red {
        /// TODO: Use markdown
        msg: String,
        /// TODO: Use markdown
        suggestion: String,
    },
}

impl CheckResult {
    /// When the check is green (ie., healthy)
    pub fn green(&self) -> bool {
        matches!(self, Self::Green)
    }
}

use anyhow::Context;
use clap::{command, Parser};
use nix_health::{traits::Check, NixHealth};
use nix_rs::{command::NixCmd, env::NixEnv, flake::url::FlakeUrl, info::NixInfo};

#[derive(Parser)]
#[command(author, version, about, long_about = None)]
pub struct Args {
    /// Include health checks defined in the given flake
    pub flake_url: Option<FlakeUrl>,

    /// Be quiet by outputting only failed checks
    #[arg(long = "quiet", short = 'q')]
    pub quiet: bool,

    /// Dump the config schema of the health checks (useful when adding them to
    /// a flake.nix)
    #[arg(long = "dump-schema")]
    pub dump_schema: bool,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    human_panic::setup_panic!();
    let args = Args::parse();

    nix_health::logging::setup_logging(args.quiet);

    if args.dump_schema {
        tracing::info!("{}", NixHealth::schema()?);
        return Ok(());
    }

    let checks = run_checks(args.flake_url).await?;

    let exit_code = NixHealth::print_report_returning_exit_code(&checks);

    std::process::exit(exit_code)
}

/// Run health checks, taking current directory flake into account if there is
/// one.
async fn run_checks(flake_url: Option<FlakeUrl>) -> anyhow::Result<Vec<Check>> {
    let nix_info = NixInfo::from_nix(&NixCmd::default())
        .await
        .with_context(|| "Unable to gather nix info")?;
    let nix_env = NixEnv::detect()
        .await
        .with_context(|| "Unable to gather system info")?;
    let action_msg = format!(
        "🩺️ Checking the health of your Nix setup ({} on {})",
        &nix_info.nix_config.system.value, &nix_env.os
    );
    let health: NixHealth = match flake_url.as_ref() {
        Some(flake_url) => {
            tracing::info!("{}, using config from flake '{}':", action_msg, flake_url);
            NixHealth::from_flake(flake_url).await
        }
        None => {
            tracing::info!("{}:", action_msg);
            Ok(NixHealth::default())
        }
    }?;
    let checks = health.run_checks(&nix_info, flake_url.clone());
    Ok(checks)
}

