/// Check that [nix_rs::config::NixConfig::max_jobs] is set to a good value.
#[derive(Debug, Default, Serialize, Deserialize, Clone)]
#[serde(default)]
pub struct MaxJobs {}

impl Checkable for MaxJobs {
    fn check(
        &self,
        nix_info: &info::NixInfo,
        _: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check> {
        let max_jobs = nix_info.nix_config.max_jobs.value;
        let check = Check {
            title: "Max Jobs".to_string(),
            info: format!("max-jobs = {}", max_jobs),
            result: if max_jobs > 1 {
                CheckResult::Green
            } else {
                CheckResult::Red {
                    msg: "You are using only 1 CPU core for nix builds".into(),
                    suggestion: format!(
                        "Set `max-jobs = auto` in {}",
                        nix_info.nix_env.os.nix_config_label()
                    ),
                }
            },
            required: true,
        };
        vec![check]
    }
}

use nix_rs::{flake::url::FlakeUrl, info};
use serde::{Deserialize, Serialize};

use crate::traits::{Check, CheckResult, Checkable};

/// Check if direnv is installed
#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(default, rename_all = "kebab-case")]
pub struct Direnv {
    pub(crate) enable: bool,
    /// Whether to produce [Check::required] checks
    pub(crate) required: bool,
}

impl Default for Direnv {
    fn default() -> Self {
        Self {
            enable: true,
            required: false,
        }
    }
}

impl Checkable for Direnv {
    fn check(&self, _nix_info: &info::NixInfo, flake_url: Option<&FlakeUrl>) -> Vec<Check> {
        let mut checks = vec![];
        if !self.enable {
            return checks;
        }

        let direnv_install_result = direnv::DirenvInstall::detect();
        checks.push(install_check(&direnv_install_result, self.required));

        match direnv_install_result.as_ref() {
            Err(_) => return checks,
            Ok(direnv_install) => {
                // If direnv is installed, check for version and then allowed_check
                // This check is currently only relevant if the flake is local and an `.envrc` exists.
                match flake_url.as_ref().and_then(|url| url.as_local_path()) {
                    None => {}
                    Some(local_path) => {
                        if local_path.join(".envrc").exists() {
                            checks.push(allowed_check(direnv_install, local_path, self.required));
                        }
                    }
                }
            }
        }

        checks
    }
}

/// [Check] that direnv was installed.
fn install_check(
    direnv_install_result: &Result<direnv::DirenvInstall, direnv::DirenvInstallError>,
    required: bool,
) -> Check {
    let setup_url = "https://nixos.asia/en/direnv#setup";
    Check {
        title: "Direnv installation".to_string(),
        info: format!(
            "direnv location = {:?}",
            direnv_install_result.as_ref().ok().map(|s| &s.bin_path)
        ),
        result: match direnv_install_result {
            Ok(direnv_install) if is_path_in_nix_store(&direnv_install.canonical_path) => {
                CheckResult::Green
            }
            Ok(direnv_install) => CheckResult::Red {
                msg: format!(
                    "direnv is installed outside of Nix ({:?})",
                    &direnv_install.canonical_path
                ),
                suggestion: format!(
                    "Install direnv via Nix, it will also manage shell integration. See <{}>",
                    setup_url
                ),
            },
            Err(e) => CheckResult::Red {
                msg: format!("Unable to locate direnv ({})", e),
                suggestion: format!("Install direnv <{}>", setup_url),
            },
        },
        required,
    }
}

/// Check that the path is in the Nix store (usually /nix/store)
fn is_path_in_nix_store(path: &std::path::Path) -> bool {
    path.starts_with("/nix/store")
}

/// [Check] that direnv was allowed on the local flake
fn allowed_check(
    direnv_install: &direnv::DirenvInstall,
    local_flake: &std::path::Path,
    required: bool,
) -> Check {
    let suggestion = format!("Run `direnv allow` under `{}`", local_flake.display());
    let direnv_allowed = direnv_install
        .status(local_flake)
        .map(|status| status.state.is_allowed());
    Check {
        title: "Direnv allowed".to_string(),
        info: format!("Local flake: {:?} (has .envrc and is allowed)", local_flake),
        result: match direnv_allowed {
            Ok(true) => CheckResult::Green,
            Ok(false) => CheckResult::Red {
                msg: "direnv was not allowed on this project".to_string(),
                suggestion,
            },
            Err(e) => CheckResult::Red {
                msg: format!("Unable to check direnv status: {}", e),
                suggestion,
            },
        },
        required,
    }
}

use bytesize::ByteSize;
use serde::{Deserialize, Serialize};

use crate::traits::{Check, CheckResult, Checkable};

/// Check if the system has enough resources
#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(default)]
pub struct System {
    enable: bool,
    required: bool,
    /// Minimum required RAM memory
    min_ram: Option<ByteSize>,
    /// Minimum required disk space
    min_disk_space: Option<ByteSize>,
}

impl Default for System {
    fn default() -> Self {
        Self {
            enable: true,
            required: false,
            // RAM requirements vary between projects.
            min_ram: None,
            // 1TiB is recommended for nix
            min_disk_space: Some(ByteSize::gb(1024)),
        }
    }
}

impl Checkable for System {
    fn check(
        &self,
        nix_info: &nix_rs::info::NixInfo,
        _: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check> {
        let mut checks = vec![];
        let nix_env = &nix_info.nix_env;
        if self.enable {
            if let Some(min_ram) = self.min_ram {
                checks.push(Check {
                    title: "RAM".to_string(),
                    info: format!(
                        "min ram = {:?}; total = {:?}",
                        min_ram, nix_env.total_memory
                    ),
                    result: if nix_env.total_memory < min_ram {
                        CheckResult::Red {
                            msg: format!("Total memory is less than {}", min_ram),
                            suggestion: "Please add more memory to your system".to_string(),
                        }
                    } else {
                        CheckResult::Green
                    },
                    required: self.required,
                });
            };
            if let Some(min_disk_space) = self.min_disk_space {
                checks.push(Check {
                    title: "Disk Space".to_string(),
                    info: format!(
                        "min disk space = {:?}; total = {:?}",
                        min_disk_space, nix_env.total_disk_space
                    ),
                    result: if nix_env.total_disk_space < min_disk_space {
                        CheckResult::Red {
                            msg: format!("Total disk space is less than {}", min_disk_space),
                            suggestion:
                                "The Nix store tends to use a lot of disk space. Please add more disk space"
                                    .to_string(),
                        }
                    } else {
                        CheckResult::Green
                    },
                    required: self.required,
                });
            };
        };
        checks
    }
}

