use std::collections::HashSet;

use nix_rs::config::TrustedUserValue;
use serde::{Deserialize, Serialize};

use crate::traits::*;

/// Check that [crate::nix::config::NixConfig::trusted_users] is set to a good value.
#[derive(Debug, Default, Serialize, Deserialize, Clone)]
#[serde(default)]
pub struct TrustedUsers {}

impl Checkable for TrustedUsers {
    fn check(
        &self,
        nix_info: &nix_rs::info::NixInfo,
        _: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check> {
        let result = if is_current_user_trusted(nix_info) {
            CheckResult::Green
        } else {
            let current_user = &nix_info.nix_env.current_user;
            let msg = format!("User '{}' not present in trusted_users", current_user);
            let suggestion = match nix_info.nix_env.os.nix_system_config_label() {
                Some(conf_label) => format!(
                    r#"Add `nix.trustedUsers = [ "root" "{}" ];` to your {}"#,
                    current_user, conf_label,
                ),
                None => format!(
                    r#"Set `trusted-users = root {}` in /etc/nix/nix.conf and then restart the Nix daemon using `sudo pkill nix-daemon`"#,
                    current_user
                ),
            };
            CheckResult::Red { msg, suggestion }
        };
        let check = Check {
            title: "Trusted Users".to_string(),
            info: format!(
                "trusted-users = {}",
                TrustedUserValue::display_original(&nix_info.nix_config.trusted_users.value)
            ),
            result,
            required: true,
        };
        vec![check]
    }
}

/// Check that [crate::nix::config::NixConfig::trusted_users] is set to a good
/// value such that the current user is trusted.
fn is_current_user_trusted(nix_info: &nix_rs::info::NixInfo) -> bool {
    let current_user = &nix_info.nix_env.current_user;
    let current_user_groups: HashSet<&String> =
        nix_info.nix_env.current_user_groups.iter().collect();
    nix_info
        .nix_config
        .trusted_users
        .value
        .iter()
        .any(|x| match x {
            TrustedUserValue::Group(x) => current_user_groups.contains(&x),
            TrustedUserValue::User(x) => x == current_user,
            TrustedUserValue::All => true,
        })
}

use nix_rs::{
    env::{AppleEmulation, MacOSArch, OS},
    info,
};
use serde::{Deserialize, Serialize};

use crate::traits::{Check, CheckResult, Checkable};

/// Check if Nix is being run under rosetta emulation
///
/// Enabled only on ARM macs.
#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(default)]
pub struct Rosetta {
    enable: bool,
    required: bool,
}

impl Default for Rosetta {
    fn default() -> Self {
        Self {
            enable: true,
            required: true,
        }
    }
}

impl Checkable for Rosetta {
    fn check(
        &self,
        nix_info: &info::NixInfo,
        _: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check> {
        let mut checks = vec![];
        if let (true, Some(emulation)) = (self.enable, get_apple_emulation(&nix_info.nix_env.os)) {
            let check = Check {
                title: "Rosetta Not Active".to_string(),
                info: format!("apple emulation = {:?}", emulation),
                result: if emulation == AppleEmulation::Rosetta {
                    CheckResult::Red {
                    msg: "Rosetta emulation will slow down Nix builds".to_string(),
                    suggestion: "Remove rosetta, see the comment by @hruan here: https://developer.apple.com/forums/thread/669486".to_string(),
                }
                } else {
                    CheckResult::Green
                },
                required: self.required,
            };
            checks.push(check);
        };
        checks
    }
}

/// Return [AppleEmulation]. Return None if not an ARM mac.

fn get_apple_emulation(system: &OS) -> Option<AppleEmulation> {
    match system {
        OS::MacOS {
            nix_darwin: _,
            arch: MacOSArch::Arm64(apple_emulation),
        } => Some(apple_emulation.clone()),
        _ => None,
    }
}

use nix_rs::version::NixVersion;

use nix_rs::info;
use serde::{Deserialize, Serialize};

use crate::traits::*;

/// Check that [nix_rs::version::NixVersion] is set to a good value.
#[derive(Debug, Serialize, Deserialize, PartialEq, Eq, Clone)]
#[serde(default, rename_all = "kebab-case")]
pub struct MinNixVersion {
    pub min_required: NixVersion,
}

impl Default for MinNixVersion {
    fn default() -> Self {
        MinNixVersion {
            min_required: NixVersion {
                major: 2,
                minor: 16,
                patch: 0,
            },
        }
    }
}

impl Checkable for MinNixVersion {
    fn check(
        &self,
        nix_info: &info::NixInfo,
        _: Option<&nix_rs::flake::url::FlakeUrl>,
    ) -> Vec<Check> {
        let val = &nix_info.nix_version;
        let check = Check {
            title: "Minimum Nix Version".to_string(),
            info: format!("nix version = {}", val),
            result: if val >= &self.min_required {
                CheckResult::Green
            } else {
                CheckResult::Red {
                    msg: format!("Your Nix version ({}) is too old; we require at least {}", val, self.min_required),
                    suggestion: "See https://nixos.org/manual/nix/stable/command-ref/new-cli/nix3-upgrade-nix.html".into(),
                }
            },
            required: true,
        };
        vec![check]
    }
}
